// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(address sendTarget, uint256 sendValue) internal {
        vm.assume(sendTarget != address(0));
        uint beforeBalanceC = address(c).balance;
        bool sendReverted;
        try c.sendMoney(sendTarget, sendValue) {
            sendReverted = false;
        } catch {
            sendReverted = true;
        }
        uint afterBalanceC = address(c).balance;
        assertTrue(sendReverted || (beforeBalanceC >= sendValue && afterBalanceC <= beforeBalanceC - sendValue));
    }

    function testFuzz_run(address sendTarget, uint256 sendValue) public {
        vm.assume(sendTarget.code.length == 0 && uint160(sendTarget) > 0xffff && sendTarget != address(this) && sendTarget != address(c) && sendTarget != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && sendTarget != 0x000000000000000000636F6e736F6c652e6c6f67 && sendTarget != 0x4e59b44847b379578588920cA78FbF26c0B4956C && sendTarget != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(sendTarget, sendValue);
    }

    receive() external payable { }
}
